"724 :   String getReadableJSTypeName(Node n, boolean dereference) {
725 : 
726 :     // The best type name is the actual type name.
727 : 
728 :     // If we're analyzing a GETPROP, the property may be inherited by the
729 :     // prototype chain. So climb the prototype chain and find out where
730 :     // the property was originally defined.
731 :     if (n.isGetProp()) {
732 :       ObjectType objectType = getJSType(n.getFirstChild()).dereference();
733 :       if (objectType != null) {
734 :         String propName = n.getLastChild().getString();
735 :         if (objectType.getConstructor() != null &&
736 :             objectType.getConstructor().isInterface()) {
737 :           objectType = FunctionType.getTopDefiningInterface(
738 :               objectType, propName);
739 :         } else {
740 :           // classes
741 :           while (objectType != null && !objectType.hasOwnProperty(propName)) {
742 :             objectType = objectType.getImplicitPrototype();
743 :           }
744 :         }
745 : 
746 :         // Don't show complex function names or anonymous types.
747 :         // Instead, try to get a human-readable type name.
748 :         if (objectType != null &&
749 :             (objectType.getConstructor() != null ||
750 :              objectType.isFunctionPrototypeType())) {
751 :           return objectType.toString() + "." + propName;
752 :         }
753 :       }
754 :     }
755 : 
756 :     JSType type = getJSType(n);
757 :     if (dereference) {
758 :       ObjectType dereferenced = type.dereference();
759 :       if (dereferenced != null) {
760 :         type = dereferenced;
761 :       }
762 :     }
763 :     if (type.isFunctionPrototypeType() ||
764 :         (type.toObjectType() != null &&
765 :          type.toObjectType().getConstructor() != null)) {
766 :       return type.toString();
767 :     }
768 :     String qualifiedName = n.getQualifiedName();
769 :     if (qualifiedName != null) {
770 :       return qualifiedName;
771 :     } else if (type.isFunctionType()) {
772 :       // Don't show complex function names.
773 :       return "function";
774 :     } else {
775 :       return type.toString();
776 :     }
777 :   }"

"1459 :   private void checkPropertyAccessHelper(JSType objectType, String propName,
1460 :       NodeTraversal t, Node n) {
1461 :     if (!objectType.isEmptyType() &&
1462 :         reportMissingProperties &&
1463 :         (!isPropertyTest(n) || objectType.isStruct())) {
1464 :       if (!typeRegistry.canPropertyBeDefined(objectType, propName)) {
1465 :         SuggestionPair pair =
1466 :             getClosestPropertySuggestion(objectType, propName);
1467 :         if (pair != null && pair.distance * 4 < propName.length()) {
1468 :           report(t, n, INEXISTENT_PROPERTY_WITH_SUGGESTION, propName,
1469 :               validator.getReadableJSTypeName(n.getFirstChild(), true),
1470 :               pair.suggestion);
1471 :         } else {
1472 :           report(t, n, INEXISTENT_PROPERTY, propName,
1473 :               validator.getReadableJSTypeName(n.getFirstChild(), true));
1474 :         }
1475 :       }
1476 :     }
1477 :   }"

"1404 :   private void visitGetProp(NodeTraversal t, Node n, Node parent) {
1405 :     // obj.prop or obj.method()
1406 :     // Lots of types can appear on the left, a call to a void function can
1407 :     // never be on the left. getPropertyType will decide what is acceptable
1408 :     // and what isn't.
1409 :     Node property = n.getLastChild();
1410 :     Node objNode = n.getFirstChild();
1411 :     JSType childType = getJSType(objNode);
1412 : 
1413 :     if (childType.isDict()) {
1414 :       report(t, property, TypeValidator.ILLEGAL_PROPERTY_ACCESS, "'.'", "dict");
1415 :     } else if (validator.expectNotNullOrUndefined(t, n, childType,
1416 :         "No properties on this expression", getNativeType(OBJECT_TYPE))) {
1417 :       checkPropertyAccess(childType, property.getString(), t, n);
1418 :     }
1419 :     ensureTyped(t, n);
1420 :   }"

"257 :   boolean expectNotNullOrUndefined(
258 :       NodeTraversal t, Node n, JSType type, String msg, JSType expectedType) {
259 :     if (!type.isNoType() && !type.isUnknownType() &&
260 :         type.isSubtype(nullOrUndefined) &&
261 :         !containsForwardDeclaredUnresolvedName(type)) {
262 : 
263 :       // There's one edge case right now that we don't handle well, and
264 :       // that we don't want to warn about.
265 :       // if (this.x == null) {
266 :       //   this.initializeX();
267 :       //   this.x.foo();
268 :       // }
269 :       // In this case, we incorrectly type x because of how we
270 :       // infer properties locally. See issue 109.
271 :       // http://code.google.com/p/closure-compiler/issues/detail?id=109
272 :       //
273 :       // We do not do this inference globally.
274 :       if (n.isGetProp() &&
275 :           !t.inGlobalScope() && type.isNullType()) {
276 :         return true;
277 :       }
278 : 
279 :       mismatch(t, n, msg, type, expectedType);
280 :       return false;
281 :     }
282 :     return true;
283 :   }"

"1365 :   boolean visitName(NodeTraversal t, Node n, Node parent) {
1366 :     // At this stage, we need to determine whether this is a leaf
1367 :     // node in an expression (which therefore needs to have a type
1368 :     // assigned for it) versus some other decorative node that we
1369 :     // can safely ignore.  Function names, arguments (children of LP nodes) and
1370 :     // variable declarations are ignored.
1371 :     // TODO(user): remove this short-circuiting in favor of a
1372 :     // pre order traversal of the FUNCTION, CATCH, LP and VAR nodes.
1373 :     int parentNodeType = parent.getType();
1374 :     if (parentNodeType == Token.FUNCTION ||
1375 :         parentNodeType == Token.CATCH ||
1376 :         parentNodeType == Token.PARAM_LIST ||
1377 :         parentNodeType == Token.VAR) {
1378 :       return false;
1379 :     }
1380 : 
1381 :     JSType type = n.getJSType();
1382 :     if (type == null) {
1383 :       type = getNativeType(UNKNOWN_TYPE);
1384 :       Var var = t.getScope().getVar(n.getString());
1385 :       if (var != null) {
1386 :         JSType varType = var.getType();
1387 :         if (varType != null) {
1388 :           type = varType;
1389 :         }
1390 :       }
1391 :     }
1392 :     ensureTyped(t, n, type);
1393 :     return true;
1394 :   }"

"1591 :   private void visitVar(NodeTraversal t, Node n) {
1592 :     // TODO(nicksantos): Fix this so that the doc info always shows up
1593 :     // on the NAME node. We probably want to wait for the parser
1594 :     // merge to fix this.
1595 :     JSDocInfo varInfo = n.hasOneChild() ? n.getJSDocInfo() : null;
1596 :     for (Node name : n.children()) {
1597 :       Node value = name.getFirstChild();
1598 :       // A null var would indicate a bug in the scope creation logic.
1599 :       Var var = t.getScope().getVar(name.getString());
1600 : 
1601 :       if (value != null) {
1602 :         JSType valueType = getJSType(value);
1603 :         JSType nameType = var.getType();
1604 :         nameType = (nameType == null) ? getNativeType(UNKNOWN_TYPE) : nameType;
1605 : 
1606 :         JSDocInfo info = name.getJSDocInfo();
1607 :         if (info == null) {
1608 :           info = varInfo;
1609 :         }
1610 : 
1611 :         checkEnumAlias(t, info, value);
1612 :         if (var.isTypeInferred()) {
1613 :           ensureTyped(t, name, valueType);
1614 :         } else {
1615 :           validator.expectCanAssignTo(
1616 :               t, value, valueType, nameType, "initializing variable");
1617 :         }
1618 :       }
1619 :     }
1620 :   }"

"2005 :   private JSType getJSType(Node n) {
2006 :     JSType jsType = n.getJSType();
2007 :     if (jsType == null) {
2008 :       // TODO(nicksantos): This branch indicates a compiler bug, not worthy of
2009 :       // halting the compilation but we should log this and analyze to track
2010 :       // down why it happens. This is not critical and will be resolved over
2011 :       // time as the type checker is extended.
2012 :       return getNativeType(UNKNOWN_TYPE);
2013 :     } else {
2014 :       return jsType;
2015 :     }
2016 :   }"

"2054 :   private void ensureTyped(NodeTraversal t, Node n, JSType type) {
2055 :     // Make sure FUNCTION nodes always get function type.
2056 :     Preconditions.checkState(!n.isFunction() ||
2057 :             type.isFunctionType() ||
2058 :             type.isUnknownType());
2059 :     // TODO(johnlenz): this seems like a strange place to check "@implicitCast"
2060 :     JSDocInfo info = n.getJSDocInfo();
2061 :     if (info != null) {
2062 :       if (info.isImplicitCast() && !inExterns) {
2063 :         String propName = n.isGetProp() ?
2064 :             n.getLastChild().getString() : "(missing)";
2065 :         compiler.report(
2066 :             t.makeError(n, ILLEGAL_IMPLICIT_CAST, propName));
2067 :       }
2068 :     }
2069 : 
2070 :     if (n.getJSType() == null) {
2071 :       n.setJSType(type);
2072 :     }
2073 :   }"

"367 :   boolean expectCanAssignToPropertyOf(NodeTraversal t, Node n, JSType rightType,
368 :       JSType leftType, Node owner, String propName) {
369 :     // The NoType check is a hack to make typedefs work OK.
370 :     if (!leftType.isNoType() && !rightType.isSubtype(leftType)) {
371 :       // Do not type-check interface methods, because we expect that
372 :       // they will have dummy implementations that do not match the type
373 :       // annotations.
374 :       JSType ownerType = getJSType(owner);
375 :       if (ownerType.isFunctionPrototypeType()) {
376 :         FunctionType ownerFn = ownerType.toObjectType().getOwnerFunction();
377 :         if (ownerFn.isInterface() &&
378 :             rightType.isFunctionType() && leftType.isFunctionType()) {
379 :           return true;
380 :         }
381 :       }
382 : 
383 :       mismatch(t, n,
384 :           "assignment to property " + propName + " of " +
385 :           getReadableJSTypeName(owner, true),
386 :           rightType, leftType);
387 :       return false;
388 :     }
389 :     return true;
390 :   }"

